//! Password hashing and the `/etc/shadow` record store for the RavenBSD root login.
//!
//! The hash is SHA-512-crypt (`$6$`, the traditional shadow format) from the vetted
//! `sha-crypt` 0.6 RustCrypto crate. The default `root` hash is generated by `build.rs` from the
//! release password and the fixed salt in [`hash`]; the image builder only installs
//! [`DEFAULT_ROOT_HASH`]/[`default_root_shadow`], never a plaintext password file.
//!
//! The store is deliberately small: one shadow record at a time, a parser/renderer, and a
//! constant-time verification call. Multi-user policy and session management are REL1.

#![cfg_attr(not(test), no_std)]
#![forbid(unsafe_code)]
#![deny(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects,
    clippy::unreachable,
    clippy::todo,
    clippy::unimplemented
)]

extern crate alloc;

pub mod errors;
pub mod hash;
pub mod shadow;

pub use errors::AuthError;
pub use hash::{
    DEFAULT_ROOT_HASH, DEFAULT_ROOT_SALT, default_root_hash, hash_password, verify_password,
};
pub use shadow::{ShadowEntry, default_root_shadow, root_line, verify_root_shadow};
